-- =========================================================
-- 03 - Carga das tabelas auxiliares
-- =========================================================
-- Tabelas de tabulação do SIASUS (TAB_SIA.zip, convertidas pelo TabWin para CREATE TABLE + INSERT):
--   cadgerrs      estabelecimentos do RS (CNES)          <- CADGERRS.dbf
--   cbo           ocupações                              <- CBO.dbf
--   s_cid         diagnósticos CID-10                    <- S_CID.dbf
--   procedimentos procedimentos SIGTAP                   <- TB_SIGTAW.dbf (tabela renomeada para "procedimentos")
-- Base Territorial do DATASUS (06-base_territorial_jun26.zip, CSV convertido para INSERT):
--   tb_municip    municípios (nome, UF, coordenadas)
--   tb_regsaud    nomes das Regiões de Saúde
--
-- Nomes de tabelas em minúsculo (o MySQL no Linux diferencia maiúsculas nos nomes de tabela).
-- Chaves primárias são criadas depois dos INSERTs, exceto na s_cid: o arquivo original contém
-- 14 códigos em minúsculo que colidem com os maiúsculos; a correção está em 05-corrige-s_cid.sql.
-- =========================================================

SET NAMES utf8mb4;
USE dbsia;


-- ---------------------------------------------------------- cadgerrs (55950 linhas)
DROP TABLE IF EXISTS cadgerrs;
CREATE TABLE cadgerrs (
  cnes CHAR(7),
  cpf_cnpj CHAR(14),
  fantasia CHAR(60),
  raz_soci CHAR(85),
  rsoc_man CHAR(60),
  logradou CHAR(40),
  num_end CHAR(10),
  compleme CHAR(20),
  bairro CHAR(20),
  cod_cep CHAR(8),
  telefone CHAR(13),
  fax CHAR(13),
  email CHAR(30),
  regsaude CHAR(4),
  micr_reg CHAR(6),
  distrsan CHAR(4),
  distradm CHAR(4),
  codufmun CHAR(6),
  excluido CHAR(1),
  dataincl DATE,
  dataexcl DATE,
  natureza CHAR(2)) DEFAULT CHARSET=utf8mb4;

ALTER TABLE cadgerrs ADD PRIMARY KEY (cnes);

-- ---------------------------------------------------------- cbo (2813 linhas)
DROP TABLE IF EXISTS cbo;
CREATE TABLE cbo (
  cbo CHAR(6),
  ds_cbo CHAR(150)) DEFAULT CHARSET=utf8mb4;

ALTER TABLE cbo ADD PRIMARY KEY (cbo);

-- ---------------------------------------------------------- s_cid (14705 linhas)
DROP TABLE IF EXISTS s_cid;
CREATE TABLE s_cid (
  cd_cod CHAR(4),
  opc CHAR(1),
  cat CHAR(1),
  subcat CHAR(1),
  cd_descr CHAR(50),
  restrsexo CHAR(1),
  campos_rad CHAR(3),
  estadio CHAR(1),
  repete_rad CHAR(1)) DEFAULT CHARSET=utf8mb4;


-- ---------------------------------------------------------- procedimentos (5736 linhas)
DROP TABLE IF EXISTS procedimentos;
CREATE TABLE procedimentos (
  ip_cod CHAR(10),
  ip_dscr CHAR(150)) DEFAULT CHARSET=utf8mb4;

ALTER TABLE procedimentos ADD PRIMARY KEY (ip_cod);

-- ---------------------------------------------------------- tb_municip (5725 linhas)
DROP TABLE IF EXISTS tb_municip;
CREATE TABLE tb_municip (
  co_municip CHAR(6) NOT NULL,
  co_municdv VARCHAR(60),
  co_status VARCHAR(60),
  co_tipo VARCHAR(60),
  ds_nome VARCHAR(60),
  uf CHAR(2),
  macrorregional VARCHAR(60),
  ds_nomepad VARCHAR(60),
  ds_observ VARCHAR(60),
  co_regiao VARCHAR(60),
  co_uf VARCHAR(60),
  co_alter VARCHAR(60),
  co_alterdv VARCHAR(60),
  in_capital VARCHAR(60),
  in_amazleg VARCHAR(60),
  in_semiar VARCHAR(60),
  in_frontzn VARCHAR(60),
  dt_instal VARCHAR(60),
  dt_extin VARCHAR(60),
  co_sucess VARCHAR(60),
  nu_ordem VARCHAR(60),
  nu_ordmap VARCHAR(60),
  nu_latitud VARCHAR(20),
  nu_longit VARCHAR(20),
  nu_altitud VARCHAR(60),
  nu_area VARCHAR(60),
  PRIMARY KEY (co_municip)
) DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------- tb_regsaud (466 linhas)
DROP TABLE IF EXISTS tb_regsaud;
CREATE TABLE tb_regsaud (
  co_regsaud CHAR(5) NOT NULL,
  co_status VARCHAR(60),
  ds_nome VARCHAR(60),
  ds_nomepad VARCHAR(60),
  ds_abrev VARCHAR(60),
  nu_ordem VARCHAR(60),
  PRIMARY KEY (co_regsaud)
) DEFAULT CHARSET=utf8mb4;

-- Conferência (linhas por tabela)
SELECT 'cadgerrs' AS tabela, COUNT(*) AS linhas FROM cadgerrs
UNION ALL SELECT 'cbo', COUNT(*) FROM cbo
UNION ALL SELECT 's_cid', COUNT(*) FROM s_cid
UNION ALL SELECT 'procedimentos', COUNT(*) FROM procedimentos
UNION ALL SELECT 'tb_municip', COUNT(*) FROM tb_municip
UNION ALL SELECT 'tb_regsaud', COUNT(*) FROM tb_regsaud;
